AqBI,KAAMF,iBAC5CF,WAAa,EACbE,eAAiBE,KAGnBpC,UACE,CAAC,QAAQ,EAAE4C,OACV,8BAA0B,EAAEG,iBAC5B,kBAAK,EAAEd,IACP,sBAAkB,EAAEI,iBAHE,CAK3B,CACF,CAAE,MAAOgC,IAAU,CACjBC,QAAQC,KAAK,CAAC,mBAAoBF,KAClCrE,UAAU,CAAC,iBAAiB,EAAEqE,IAAIG,OAAO,EAAIH,KAAK,EAClD,MACF,CACAI,sBAAsBnC,KACxB,GAEF,CAAE,MAAO+B,IAAU,CACjBC,QAAQC,KAAK,CAACF,KACdrE,UAAU,CAAC,OAAO,EAAEqE,IAAIG,OAAO,EAAIH,IAAI,0BAA0B,CAAC,CACpE,CACF","names":["MP","WASM_URL","video","document","getElementById","canvas","ctx","getContext","stats","setStatus","html","innerHTML","isVisible","p","visibility","POSE","main","srcObject","navigator","mediaDevices","getUserMedia","width","height","audio","play","W","videoWidth","H","videoHeight","PoseLandmarker","FilesetResolver","fileset","forVisionTasks","landmarker","createFromOptions","baseOptions","modelAssetPath","delegate","runningMode","numPoses","lastVideoTime","frameCount","fps","fpsWindowStart","performance","now","totalDetections","loop","readyState","currentTime","result","detectForVideo","clearRect","people","landmarks","length","visibleKeypoints","lm","start","end","strokeStyle","lineWidth","POSE_CONNECTIONS","a","b","beginPath","moveTo","x","y","lineTo","stroke","fillStyle","arc","Math","PI","fill","filter","round","err","console","error","message","requestAnimationFrame"],"ignoreList":[],"sources":["../../src/client/poselive.ts"],"sourcesContent":["// Pose Camera Analytics — your code, served from the instance (classic UI page).
// MediaPipe is loaded via dynamic import so the SDK bundler leaves it external.
const MP = "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.14";
const WASM_URL = MP + "/wasm";
const MODEL_URL = "https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_lite/float16/1/pose_landmarker_lite.task";

const SKELETON_COLOR = "#00FFFF"; // cyan
const KEYPOINT_COLOR = "#00FF00"; // green
const VIS_THRESHOLD = 0.5;

const video: any = document.getElementById("video");
const canvas: any = document.getElementById("canvas");
const ctx: any = canvas.getContext("2d");
const stats: any = document.getElementById("stats");

const setStatus = (html: string) => { stats.innerHTML = html; };
const isVisible = (p: any) => (p.visibility ?? 1) >= VIS_THRESHOLD;

let POSE: any = null; // PoseLandmarker class (for POSE_CONNECTIONS)

function drawPose(landmarks: any, W: number, H: number) {
  ctx.strokeStyle = SKELETON_COLOR;
  ctx.lineWidth = 3;
  for (const { start, end } of POSE.POSE_CONNECTIONS) {
    const a = landmarks[start], b = landmarks[end];
    if (!a || !b || !isVisible(a) || !isVisible(b)) continue;
    ctx.beginPath();
    ctx.moveTo(a.x * W, a.y * H);
    ctx.lineTo(b.x * W, b.y * H);
    ctx.stroke();
  }
  ctx.fillStyle = KEYPOINT_COLOR;
  for (const p of landmarks) {
    if (!isVisible(p)) continue;
    ctx.beginPath();
    ctx.arc(p.x * W, p.y * H, 5, 0, Math.PI * 2);
    ctx.fill();
  }
}

async function main() {
  try {
    // 1. Start the camera
    setStatus("Requesting camera…");
    const stream = await navigator.mediaDevices.getUserMedia({ video: { width: 640, height: 480 }, audio: false });
    video.srcObject = stream;
    await video.play();

    const W = video.videoWidth || 640;
    const H = video.videoHeight || 480;
    canvas.width = W;
    canvas.height = H;

    // 2. Load the model on the CPU
    setStatus("Loading model… (first load can take a minute)");
    const vision: any = await import(/* @vite-ignore */ (MP));
    const { PoseLandmarker, FilesetResolver } = vision;
    POSE = PoseLandmarker;
    const fileset = await FilesetResolver.forVisionTasks(WASM_URL);
    const landmarker = await PoseLandmarker.createFromOptions(fileset, {
      baseOptions: { modelAssetPath: MODEL_URL, delegate: "CPU" },
      runningMode: "VIDEO",
      numPoses: 2,
    });

    // 3. Detection loop with analytics
    let lastVideoTime = -1;
    let frameCount = 0, fps = 0, fpsWindowStart = performance.now();
    let totalDetections = 0;

    function loop() {
      try {
        if (video.readyState >= 2 && video.currentTime !== lastVideoTime) {
          lastVideoTime = video.currentTime;

          const result = landmarker.detectForVideo(video, performance.now());
          ctx.clearRect(0, 0, W, H);

          const people = result.landmarks.length;
          let visibleKeypoints = 0;
          for (const lm of result.landmarks) {
            drawPose(lm, W, H);
            visibleKeypoints += lm.filter(isVisible).length;
          }

          frameCount++;
          totalDetections += people;
          const now = performance.now();
          if (now - fpsWindowStart >= 1000) {
            fps = Math.round(frameCount * 1000 / (now - fpsWindowStart));
            frameCount = 0;
            fpsWindowStart = now;
          }

          setStatus(
            `People: ${people}<br>` +
            `Keypoints: 33 per person (${visibleKeypoints} visible)<br>` +
            `FPS: ${fps}<br>` +
            `Total detections: ${totalDetections}`
          );
        }
      } catch (err: any) {
        console.error("Detection error:", err);
        setStatus(`Detection error: ${err.message || err}`);
        return;
      }
      requestAnimationFrame(loop);
    }
    loop();
  } catch (err: any) {
    console.error(err);
    setStatus(`Error: ${err.message || err}<br>Press F12 for details.`);
  }
}

main();

export {};
"]}
